def parse(pattern):
    """Turn a pattern into a tree."""
    items = []
    for char in pattern:
        if char in QUANTIFIERS:
            if not items:
                raise ValueError(f"{char!r} has nothing to repeat")
            items[-1] = (QUANTIFIERS[char], items[-1])
        elif char == ".":
            items.append(("any",))
        else:
            items.append(("lit", char))
    return ("cat", tuple(items))


